import{_ as e,o as l,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"支持的文件管理器与对话框集成","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/file-manager-support.md","filePath":"zh-CN/user-guide/file-manager-support.md","lastUpdated":1787586465000}'),n={name:"zh-CN/user-guide/file-manager-support.md"};function d(s,t,i,o,g,f){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="支持的文件管理器与对话框集成" tabindex="-1">支持的文件管理器与对话框集成 <a class="header-anchor" href="#支持的文件管理器与对话框集成" aria-label="Permalink to &quot;支持的文件管理器与对话框集成&quot;">​</a></h1><p>Lertaro 不仅是一款独立的桌面启动器，更具备深度嵌入各类文件资源管理器与软件对话框的强大集成能力。通过无缝接管文件交互，极大提升文件打开、保存与目录跳转的效率。</p><h2 id="_1-三大核心集成能力" tabindex="-1">1. 三大核心集成能力 <a class="header-anchor" href="#_1-三大核心集成能力" aria-label="Permalink to &quot;1. 三大核心集成能力&quot;">​</a></h2><p>根据目标宿主窗口的特性，Lertaro 的集成最多可提供以下三种核心能力：</p><ul><li><strong>内嵌搜索（Inline Search）</strong>：Lertaro 的极速搜索框直接嵌入到目标窗口顶部或对话框内部，无需离开当前工作界面即可在当前目录或全局发起检索。</li><li><strong>快速导航（Quick Navigation）</strong>：在目标窗口空白处点击鼠标中键（或双击左键），或点击内嵌搜索框的图标，即可弹出包含当前已打开文件夹、收藏夹、最近历史与自定义快捷目录的级联菜单。</li><li><strong>活动路径检测（Active Path Detection）</strong>：实时感知宿主窗口当前所处的物理文件目录，自动将搜索范围智能限定在当前目录内，或用于解析相对路径操作。</li></ul><h2 id="_2-系统原生组件支持-内置开箱即用" tabindex="-1">2. 系统原生组件支持（内置开箱即用） <a class="header-anchor" href="#_2-系统原生组件支持-内置开箱即用" aria-label="Permalink to &quot;2. 系统原生组件支持（内置开箱即用）&quot;">​</a></h2><p>以下系统原生组件均由 Lertaro 核心引擎直接支持，无需单独安装或配置任何插件：</p><table tabindex="0"><thead><tr><th style="text-align:left;">宿主窗口类型</th><th style="text-align:left;">内嵌搜索</th><th style="text-align:left;">快速导航触发方式</th><th style="text-align:left;">活动路径检测</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows 文件资源管理器</strong></td><td style="text-align:left;">支持</td><td style="text-align:left;">空白区域双击左键或点击鼠标中键</td><td style="text-align:left;">支持</td></tr><tr><td style="text-align:left;"><strong>现代打开/保存文件对话框</strong></td><td style="text-align:left;">支持（直接嵌入对话框）</td><td style="text-align:left;">鼠标中键，或左键点击内嵌搜索框 Logo 图标</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>经典打开/保存文件对话框</strong></td><td style="text-align:left;">支持</td><td style="text-align:left;">鼠标中键，或左键点击内嵌搜索框 Logo 图标</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>经典“浏览文件夹”对话框</strong></td><td style="text-align:left;">支持</td><td style="text-align:left;">鼠标中键，或左键点击内嵌搜索框 Logo 图标</td><td style="text-align:left;">—</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>在各类文件选择对话框中，由于 Lertaro 已经直接内嵌在对话框内部，因此无需额外的活动路径检测；点击快速导航中的目标后，对话框会直接精准跳转到该目录。</p></div><h2 id="_3-专业第三方文件管理器支持-可选插件" tabindex="-1">3. 专业第三方文件管理器支持（可选插件） <a class="header-anchor" href="#_3-专业第三方文件管理器支持-可选插件" aria-label="Permalink to &quot;3. 专业第三方文件管理器支持（可选插件）&quot;">​</a></h2><p>针对高级用户常用的第三方文件管理工具，Lertaro 提供了深度对接插件。你可以在<a href="./settings/plugins.html"><strong>设置 → 插件</strong></a>中按需启用，并在各插件的<strong>配置</strong>面板中单独开关内嵌搜索与快速导航：</p><table tabindex="0"><thead><tr><th style="text-align:left;">文件管理器</th><th style="text-align:left;">内嵌搜索</th><th style="text-align:left;">快速导航触发方式</th><th style="text-align:left;">活动路径检测</th><th style="text-align:left;">核心通信技术与协议</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Directory Opus</strong></td><td style="text-align:left;">支持</td><td style="text-align:left;">文件列表区域点击鼠标中键</td><td style="text-align:left;">支持</td><td style="text-align:left;"><code>WM_COPYDATA</code> 官方远程控制接口</td></tr><tr><td style="text-align:left;"><strong>Total Commander</strong></td><td style="text-align:left;">支持</td><td style="text-align:left;">文件列表区域点击鼠标中键</td><td style="text-align:left;">支持</td><td style="text-align:left;"><code>WM_COPYDATA</code> 官方消息接口</td></tr><tr><td style="text-align:left;"><strong>XYplorer</strong></td><td style="text-align:left;">支持</td><td style="text-align:left;">文件列表区域点击鼠标中键</td><td style="text-align:left;">支持</td><td style="text-align:left;">专用进程接口通信</td></tr><tr><td style="text-align:left;"><strong>Files</strong></td><td style="text-align:left;">支持</td><td style="text-align:left;">文件列表区域点击鼠标中键</td><td style="text-align:left;">支持</td><td style="text-align:left;">Windows UI Automation 现代化自动化接口</td></tr><tr><td style="text-align:left;"><strong>One Commander</strong></td><td style="text-align:left;">支持</td><td style="text-align:left;">文件列表区域点击鼠标中键</td><td style="text-align:left;">支持</td><td style="text-align:left;">Windows UI Automation 现代化自动化接口</td></tr></tbody></table><h3 id="directory-opus-专属深度集成" tabindex="-1">Directory Opus 专属深度集成 <a class="header-anchor" href="#directory-opus-专属深度集成" aria-label="Permalink to &quot;Directory Opus 专属深度集成&quot;">​</a></h3><ul><li><strong>递归文件夹大小列（Lertaro 大小）</strong>：启用 Directory Opus 插件中的“启用 Lertaro 大小列”后，Lertaro 会自动向 Directory Opus 注入自定义脚本列。该列直接从 Lertaro 的内存索引读取文件夹递归总容量，<strong>完全无需扫描磁盘</strong>即可秒级呈现整个磁盘所有文件夹的实际体积。</li><li><strong>持久化配置</strong>：在 Directory Opus 的列选择器中添加“Lertaro 大小”列后，依次点击<strong>文件夹 → 文件夹格式 → 保存 → 将格式保存给所有文件夹</strong>即可全局生效。</li></ul><h3 id="everything-兼容服务-ipc" tabindex="-1">Everything 兼容服务 (IPC) <a class="header-anchor" href="#everything-兼容服务-ipc" aria-label="Permalink to &quot;Everything 兼容服务 (IPC)&quot;">​</a></h3><p>在<a href="./settings/general.html#系统"><strong>设置 → 通用 → 系统</strong></a>中勾选**启用 Everything 兼容服务 (IPC)**后，Lertaro 会在后台模拟标准的 Everything Win32 IPC 接口。Directory Opus、Total Commander、Flow Launcher 等第三方软件无需额外安装或运行 Everything，即可直接通过原有的 Everything 插件调用 Lertaro 的极速内存索引。</p><h2 id="_4-常用软件自绘对话框支持-专用插件" tabindex="-1">4. 常用软件自绘对话框支持（专用插件） <a class="header-anchor" href="#_4-常用软件自绘对话框支持-专用插件" aria-label="Permalink to &quot;4. 常用软件自绘对话框支持（专用插件）&quot;">​</a></h2><p>许多专业软件并未使用 Windows 原生对话框，而是自绘了特殊窗口。Lertaro 为以下主流软件的专用对话框提供了定制化内嵌支持：</p><table tabindex="0"><thead><tr><th style="text-align:left;">软件名称与对话框类型</th><th style="text-align:left;">内嵌搜索</th><th style="text-align:left;">快速导航触发方式</th><th style="text-align:left;">适配说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>WPS Office</strong> 打开/保存对话框</td><td style="text-align:left;">支持</td><td style="text-align:left;">鼠标中键，或点击内嵌 Logo 图标</td><td style="text-align:left;">全面覆盖 WPS 文字、表格、演示与 PDF 组件</td></tr><tr><td style="text-align:left;"><strong>WinRAR</strong> 解压对话框</td><td style="text-align:left;">支持</td><td style="text-align:left;">鼠标中键，或点击内嵌 Logo 图标</td><td style="text-align:left;">解压文件时快速定位目标解压目录</td></tr><tr><td style="text-align:left;"><strong>Bandizip</strong> 解压对话框</td><td style="text-align:left;">支持</td><td style="text-align:left;">鼠标中键，或点击内嵌 Logo 图标</td><td style="text-align:left;">快速指定解压输出路径</td></tr><tr><td style="text-align:left;"><strong>Bandizip</strong> 添加文件对话框</td><td style="text-align:left;">支持</td><td style="text-align:left;">鼠标中键，或点击内嵌 Logo 图标</td><td style="text-align:left;">压缩打包时快速选择源文件</td></tr><tr><td style="text-align:left;"><strong>AutoCAD</strong> 打开/保存对话框</td><td style="text-align:left;">支持</td><td style="text-align:left;">鼠标中键，或点击内嵌 Logo 图标</td><td style="text-align:left;">适配工程图纸的快速归档与调用</td></tr></tbody></table><p>各插件通过识别窗口底层的控件结构与句柄层级进行挂载，不受软件多语言界面或不同版本界面微调的影响。</p>',20)])])}const x=e(n,[["render",d]]);export{h as __pageData,x as default};
